mapper.select:
SELECT COUNT(*) FROM payment_channel_receipt
WHERE payment_id=#{paymentId} AND channel_status='SUCCESS'
  AND BINARY channel_trade_no=BINARY #{tradeNo} AND paid_amount=#{paidAmount} AND paid_at=#{paidAt}

mapper.update:
UPDATE payment_order SET status='PAID',dispatch_state='OBSERVED',channel_trade_no=#{tradeNo},
  channel_paid_amount=#{paidAmount},paid_at=#{paidAt},success_event_id=#{eventId},
  version=version+1,updated_at=#{now} WHERE id=#{paymentId}

UPDATE payment_order SET status=#{status},dispatch_state='OBSERVED',
  channel_trade_no=COALESCE(channel_trade_no,#{tradeNo}),version=version+1,
  updated_at=#{now} WHERE id=#{paymentId}

UPDATE payment_dispatch SET state='CLOSE_MAY_HAVE_SENT',
  close_may_have_sent_at=UTC_TIMESTAMP(3),version=version+1,
  updated_at=UTC_TIMESTAMP(3) WHERE payment_id=#{paymentId}

mapper.select:
SELECT channel_response_sha256 FROM payment_channel_receipt WHERE payment_id=#{paymentId}
  AND receipt_source='QUERY' AND channel_status='CLOSE'
  AND channel_response_sha256=#{sha} LIMIT 1 FOR UPDATE
